                                                                                                                                                                                                                
  CREATE TABLE "TENANT_EVENT_UPGRADE_RECORDS"                                                                                                                                                        
   (	"UPGRADE_RECORDS_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"TENANT_ID" NUMBER DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                                  
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                     
	"UPDATE_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                            
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                     
	"CREATION_DATE" DATE DEFAULT SYSDATE NOT NULL ENABLE,                                                                                                                                                          
	"REMARK" NVARCHAR2(256),                                                                                                                                                                                       
	"EVENT_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                       
	"UPGRADE_LEVEL" NUMBER DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                              
	"ESTIMATED_UPGRADE_TIME" DATE,                                                                                                                                                                                 
	"ACTUAL_UPGRADE_TIME" DATE,                                                                                                                                                                                    
	"STATUS" NVARCHAR2(20) NOT NULL ENABLE,                                                                                                                                                                        
	"EXT_ORG_ID" NUMBER(20,0),                                                                                                                                                                                     
	"UPGRADE_EXT_USER_ID" NUMBER(20,0),                                                                                                                                                                            
	"UPGRADED_EXT_USER_ID" NUMBER(20,0),                                                                                                                                                                           
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                  
	 PRIMARY KEY ("UPGRADE_RECORDS_ID")                                                                                                                                                                            
  USING INDEX  ENABLE,                                                                                                                                                                                          
	 CHECK (STATUS IN ('WAIT', 'DONE')) ENABLE                                                                                                                                                                     
   ) ;                                                                                                                                                                                                          

